  /**
   *  Updates the properties of a given ContractAsset using key-value pairs from a list of arguments. 
   *  The method expects the argument list to contain pairs in the format:  
   *  [value1, setKey1, value2, setKey2, ...], where each `setKey` should start with "set". 
   *  <p>If the list has two or fewer elements, no updates are performed. Each key is normalized by  
   *  removing the "set" prefix and lowercasing the remainder before passing it to the asset's  
   *  updateProperty} method. 
   *  @param asset the asset whose properties are to be updated 
   *  @param args  a list of alternating values and setter keys (e.g., "100", "setBalance")
   */
  private static void updateAssetProperties(ContractAsset asset, ArrayList<String> args) {
    if (args.size() <= 2) {
      return;
    }
    for (int i = 0; i < args.size() - 1; i = i + 2) {
      String value = args.get(i);
      String setKey = args.get(i + 1).toLowerCase();
      if (setKey.startsWith("set")) {
        setKey = setKey.substring(3);
        asset.updateProperty(setKey, value);
      }
    }
  }

